class Solution {
public:
    int averageValue(vector<int>& nums) {
        int sum=0,cnt=0;
        for(auto it:nums)
        {
            if(it%3==0 and it%2==0)
            {
                cnt+=1;
                sum+=it;
            }
        }
        return cnt==0?0:(sum/cnt);
    }
};

class Solution(object):
    def averageValue(self, nums):
        """
        :type nums: List[int]
        :rtype: int
        """
        num_sum, num_cnt = 0, 0
        for num in nums:
            if num % 2 == 0 and num % 3 == 0:
                num_sum += num
                num_cnt += 1
        return 0 if num_cnt == 0 else num_sum // num_cnt
